"""Offline Batch4 gallery, reusing established Batch1/2/3 styles and controls."""
from pathlib import Path
import json
from html import escape
ROOT=Path(__file__).resolve().parent
assets=json.loads((ROOT/'manifest.json').read_text())['assets']
descriptions={
'A':'An intact reserve maintenance car beneath a root canopy. Dark cab, obsolete route display, evacuation pictograms, rail switch and walkable siding.',
'B':'Inside the same reserve car before power is restored. The original molded-plastic concierge face remains recessed behind an unlit panel.',
'C':'The authored emergency-spur result: the reserve car has broken through an advertising wall, the conductor has risen, and visitors applaud.',
'D':'Independently authored conversation background: empty driver housing, matching crash concourse, applauding visitors and a printed damage form.',
'E':'One transparent talking foreground: the same cream molded-plastic face and teal visor, now raised on its console-mounted telescoping neck.',
'F':'An underground station with glowing ticket machine, zero fare, closed turnstile, unchecked certification panel and crossed-out bathroom sign.'}
comparisons=[('transit-material-continuity','Approved tour tram → approved rooted tour tram → new reserve cab'),('reserve-state-continuity','Parked reserve siding → inactive cab → authored activated crash'),('crash-portrait-continuity','314×206 crash scene → independently authored 564×278 conversation'),('portrait-layer-comparison','Opaque background alone → background plus separate conductor'),('character-distinction','Approved Groundskeeper → distinct Courtesy Conductor'),('service-station-continuity','Approved service architecture → underground station')]
def fig(stem,title,cls=''):
 return f'<figure class="{cls}"><div class="scroll"><img class="pixel scaled" data-stem="{stem}" src="previews/{stem}-native.png" alt="{escape(title)}"></div><figcaption>{escape(title)}</figcaption></figure>'
cards=[]
for a in assets:
 k=a['id'];stem=Path(a['candidatePath']).stem;title={'D':'Concourse conversation background','E':'Courtesy Conductor — talking'}.get(k,a['registryKey'].split('/')[-1].replace('_',' ').title());w,h=a['dimensions']
 cards.append(f'<article class="asset" id="asset-{k}" data-width="{w}" data-height="{h}"><header><div class="eyebrow">{k} / {a["mode"]} {w}×{h} / generated, unselected</div><h3>{title}</h3><div class="id"><code>{a["registryKey"]}</code></div><p>{descriptions[k]}</p></header>'+fig(stem,title)+f'<div class="asset-links"><a href="{a["candidatePath"]}">Native candidate PNG</a><a href="previews/{stem}-4x.png">Exact 4× preview</a><a href="{a["source"]}">Original detailed source</a><a href="prompts/{k}-v01.txt">Exact prompt</a></div></article>')
docs=[('README.md','Batch 4 handoff','Source pins, file contracts and reproducible workflow'),('BATCH3_APPROVAL.md','Batch 3 final approval','Seven owner hashes and public preview verification'),('ARTWORK_CONTINUITY_REVIEW.md','Visual review','State, character and native-resolution findings'),('STORY_CONTINUITY.md','Canonical story context','All six complete records and associated narrative nodes'),('VISUAL_DIRECTION.md','Visual direction','Approved transit style and distinct character identity'),('qa.json','Pixel and alpha QA','Dimensions, palette, alpha, masks and preservation'),('manifest.json','Candidate manifest','Exact six paths and SHA-256 hashes'),('generation-records.json','Generation provenance','Prompts, reference roles and original source paths'),('SOURCE_SHA256SUMS.txt','Source hashes','Raw generations, prompts and canonical snapshots'),('REMAINING_QUEUE.md','Remaining Chapter 2 queue','23 records after Batch 4'),('build_review.py','Deterministic processing','Native exports, alpha threshold and notice masks'),('STORYBOARD_SYNC.md','Publication receipt','Generated statuses, canonical QA and Pages')]
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Biology Park · Batch 4 · Review</title><link rel="stylesheet" href="gallery.css"></head><body><header><div class="eyebrow">The Acceptable Error / Chapter 2 / Batch 4 / November 17, 2026</div><h1>Reserve transit<br><span style="color:#b9c9b1">and the Courtesy Conductor.</span></h1><p><span class="status">Six generated candidates · owner / Art Director selection pending</span></p><p class="muted">Batch 3 is finally approved and registered. Its selected pixels and all earlier approved art are unchanged. These six new images remain generated and unselected.</p><nav aria-label="Review sections"><a href="#assets">Six assets</a><a href="#portrait">Portrait layers</a><a href="#continuity">Continuity comparisons</a><a href="#evidence">QA and sources</a></nav></header><div class="toolbar"><div class="toolbar-inner"><div class="button-group" role="group" aria-label="Preview scale"><span class="group-label">View</span><button type="button" data-scale="1" aria-pressed="true">Native pixels</button><button type="button" data-scale="4" aria-pressed="false">Exact 4×</button></div><span class="muted" style="font-size:12px">Nearest-neighbor PNGs · full-size images scroll · no fractional scaling</span></div></div><main><section id="assets"><div class="eyebrow">A–F / actual generated artwork</div><h2>Four scenes and two portrait layers</h2><p class="note">Scene candidates are opaque RGB 314×206, with exact 1256×824 previews. The separately authored portrait background is RGB 564×278; the conductor foreground is transparent RGBA 564×278. Their exact 4× previews are 2256×1112. Original detailed sources are retained.</p>'''
html+=fig('four-scenes','Reserve Siding · Reserve Tram · Concourse Crash · Abandoned Station')+''.join(cards)
html+='''</section><section id="portrait"><div class="eyebrow">Same viewpoint / separate reusable layers</div><h2>Inspect the conversation layers</h2><p>D is a new wide generation, not an enlarged or cropped scene. E is one separate foreground pose. Both use the same canvas origin with no translation, cropping or extra scale adjustment.</p><div class="button-group" role="group" aria-label="Portrait layers"><button type="button" data-layer="both" aria-pressed="true">Composite</button><button type="button" data-layer="background" aria-pressed="false">Background only</button><button type="button" data-layer="machine" aria-pressed="false">Conductor only</button></div><div class="button-group" role="group" aria-label="Alpha inspection backdrop"><span class="group-label">Backdrop</span><button type="button" data-backdrop="checker" aria-pressed="true">Checkerboard</button><button type="button" data-backdrop="dark" aria-pressed="false">Dark</button><button type="button" data-backdrop="light" aria-pressed="false">Light</button></div><figure><div class="scroll"><div class="layer-stage" data-layer="both" style="width:564px;height:278px"><img class="bg scaled" data-stem="D-concourse-portrait-background" src="previews/D-concourse-portrait-background-native.png" alt="Independently authored opaque conversation background"><img class="fg scaled" data-stem="E-courtesy-conductor-talking" src="previews/E-courtesy-conductor-talking-native.png" alt="Separate transparent Courtesy Conductor foreground"></div></div><figcaption>Both layers are independently downloadable. The original source alpha is retained in source/history; the native foreground uses the established threshold128 pixel-export step.</figcaption></figure>'''
for stem,label in [('portrait-alpha-checker','Foreground on checkerboard'),('portrait-alpha-dark','Foreground on dark'),('portrait-alpha-light','Foreground on light'),('portrait-alpha-mask','Native binary alpha: white = conductor, black = transparent')]:html+=fig(stem,label)
html+='</section><section id="continuity"><div class="eyebrow">Approved references / authored states</div><h2>Continuity comparisons</h2><p>The tour tram establishes materials and technology. The reserve car and its conductor are distinct. Only the explicitly authored concourse result depicts a crash and active character.</p>'
html+=''.join(fig(s,t,'comparison') for s,t in comparisons)
html+='</section><section id="evidence"><div class="eyebrow">Evidence / provenance / handoff</div><h2>Technical and visual findings</h2><figure><div class="scroll"><img class="pixel" src="previews/palette.png" alt="Existing approved 64-color palette"></div><figcaption>Existing owner-selected palette; no dithering or retraining. Pixel checks are separate from creative selection.</figcaption></figure><div class="docs">'
html+=''.join(f'<a class="doc" href="{p}"><strong>{t}</strong><span>{d}</span></a>' for p,t,d in docs)
html+='</div><details><summary>Preserved native notice polish and alpha processing</summary><p>A/B/F microlettering interiors were simplified to deliberate administrative bars. Pictograms, route dots and the zero-fare numeral remain. Allowed/changed masks prove zero changes outside those notice regions. E uses the same native alpha threshold as the approved Batch 1 foreground; original soft-alpha pixels remain archived.</p>'
for k in 'ABF':
 html+=fig(k+'-signage-before-after',k+' notice: original normalized export → final candidate')+f'<p><a href="masks/{k}-signage-allowed.png">{k} allowed mask</a> · <a href="masks/{k}-signage-changed.png">{k} changed pixels</a></p>'
html+='''<p><a href="processing-history/normalization-v01/manifest.json">Original normalized exports before notice polish and alpha threshold</a></p></details></section></main><footer>Six generated candidates · no self-approval or gameplay integration · prior approved artwork preserved.</footer><script>
'use strict';
function setScale(scale){document.querySelectorAll('[data-scale]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.scale)===scale)));document.querySelectorAll('.scaled').forEach(img=>{img.removeAttribute('width');img.removeAttribute('height');img.src='previews/'+img.dataset.stem+(scale===4?'-4x.png':'-native.png');});const stage=document.querySelector('.layer-stage');stage.style.width=(564*scale)+'px';stage.style.height=(278*scale)+'px';}
document.querySelectorAll('[data-scale]').forEach(b=>b.addEventListener('click',()=>setScale(Number(b.dataset.scale))));
document.querySelectorAll('[data-layer]').forEach(b=>{if(b.tagName==='BUTTON')b.addEventListener('click',()=>{document.querySelector('.layer-stage').dataset.layer=b.dataset.layer;document.querySelectorAll('button[data-layer]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});});
document.querySelectorAll('[data-backdrop]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('.layer-stage').className='layer-stage '+(b.dataset.backdrop==='checker'?'':b.dataset.backdrop);document.querySelectorAll('[data-backdrop]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}));
</script></body></html>'''
(ROOT/'index.html').write_text(html)
print('Offline gallery built with native/4x, portrait layer and alpha backdrop controls.')
